// Generates src/styles/tokens.css from src/config/theme.json and the fixed scales below.
// Do not edit the generated file: change theme.json or this script and run `npm run tokens`.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const theme = JSON.parse(readFileSync(resolve(root, 'src/config/theme.json'), 'utf8'))

const decl = (obj) => Object.entries(obj).map(([k, v]) => `  --${k}: ${v};`).join('\n')

const scales = {
  space: { 1: '0.25rem', 2: '0.5rem', 3: '0.75rem', 4: '1rem', 5: '1.25rem', 6: '1.5rem', 8: '2rem', 10: '2.5rem', 12: '3rem' },
  radius: { sm: '0.375rem', md: '0.5rem', lg: '0.75rem', xl: '1rem', full: '9999px' },
  'font-size': { xs: '0.75rem', sm: '0.875rem', base: '1rem', lg: '1.125rem', xl: '1.25rem', '2xl': '1.5rem', '3xl': '1.875rem' },
  'font-weight': { normal: '400', medium: '500', semibold: '600', bold: '700' },
  'shadow': {
    sm: '0 1px 2px rgb(15 23 42 / 0.06)',
    md: '0 4px 12px rgb(15 23 42 / 0.08)',
    lg: '0 12px 32px rgb(15 23 42 / 0.14)',
  },
  z: { base: '0', sticky: '20', overlay: '40', modal: '50', toast: '60' },
  duration: { fast: '150ms', base: '220ms', slow: '320ms' },
  easing: { standard: 'cubic-bezier(0.2, 0.8, 0.2, 1)', exit: 'ease-in' },
}

const scaleBlock = Object.entries(scales)
  .flatMap(([group, values]) => Object.entries(values).map(([k, v]) => `  --${group}-${k}: ${v};`))
  .join('\n')

const css = `/* GENERATED by scripts/build-tokens.mjs from src/config/theme.json. Do not edit. */
:root {
${decl(theme.colors.light)}
  --font-sans: 'Inter', 'Noto Sans Devanagari', 'Noto Sans Telugu', ui-sans-serif, system-ui, sans-serif;
${scaleBlock}
  color-scheme: light;
}

:root.dark,
:root.dark {
${decl(theme.colors.dark)}
  color-scheme: dark;
}
`

writeFileSync(resolve(root, 'src/styles/tokens.css'), css)
console.log('tokens written: src/styles/tokens.css')
